/// Whether `name` is in the sorted `list`.
pub fn contains(list: &[&str], name: &str) -> bool {
    list.binary_search(&name).is_ok()
}

/// The plugin module that owns `name`, if core Pylint does not.
pub fn owner(name: &str) -> Option<&'static str> {
    PLUGIN_NAMES
        .binary_search_by(|(probe, _)| probe.cmp(&name))
        .ok()
        .map(|index| PLUGIN_NAMES[index].1)
}
